#ifndef ACLNNFALLBACK_OPAPI_TWOSTAGES_H_
#define ACLNNFALLBACK_OPAPI_TWOSTAGES_H_

#include <dlfcn.h>

#include <functional>
#include <tuple>
#include <type_traits>
#include <unordered_map>
