81	inline std::vector<std::string> split_str(std::string s, const std::string &del)
82	{
83	    size_t end = s.find(del);
84	    std::vector<std::string> path_list;
85	    while (end != std::string::npos) {
86	        path_list.push_back(s.substr(0, end));
87	        s.erase(s.begin(), s.begin() + end + 1);
88	        end = s.find(del);
89	    }
90	    path_list.push_back(s);
91	    return path_list;
92	}
