94	inline bool is_file_exist(const std::string &path)
95	{
96	    if (path.empty() || path.size() > OMNI_INFER_PATH_MAX) {
97	        return false;
98	    }
99	    return (access(path.c_str(), F_OK) == 0) ? true : false;
100	}
