102	inline  std::string real_path(const std::string &path)
103	{
104	    if (path.empty() || path.size() > OMNI_INFER_PATH_MAX) {
105	        return "";
106	    }
107	    char realPath[OMNI_INFER_PATH_MAX] = {0};
108	    if (realpath(path.c_str(), realPath) == nullptr) {
109	        return "";
110	    }
111	    return std::string(realPath);
112	}
