114	inline std::vector<std::string> get_custom_lib_path()
115	{
116	    std::string ascendCustomOpppath = std::getenv("ASCEND_CUSTOM_OPP_PATH");
117	    std::vector<std::string> custom_lib_path_list;
118	
119	    if (ascendCustomOpppath.empty()) {
120	        OP_LOGW("aclnnfallback", "ASCEND_CUSTOM_OPP_PATH is not exists");
121	        return std::vector<std::string>();
122	    }
123	
124	    std::string ascend_custom_opppath_str(ascendCustomOpppath);
125	    // split string with ":"
126	    custom_lib_path_list = split_str(ascend_custom_opppath_str, ":");
127	    if (custom_lib_path_list.empty()) {
128	        return std::vector<std::string>();
129	    }
130	    for (auto &it : custom_lib_path_list) {
131	        it = it + "/op_api/lib/";
132	    }
133	
134	    return custom_lib_path_list;
135	}
