137	inline std::vector<std::string> get_default_custom_lib_path()
138	{
139	    std::string ascendOppPath = std::getenv("ASCEND_OPP_PATH");
140	    std::vector<std::string> default_vendors_list;
141	
142	    if (ascendOppPath.empty()) {
143	        OP_LOGW("aclnnfallback", "ASCEND_OPP_PATH is not exists");
144	        return std::vector<std::string>();
145	    }
146	
147	    std::string vendors_path(ascendOppPath);
148	    vendors_path = vendors_path + "/vendors";
149	    std::string vendors_config_file = real_path(vendors_path + "/config.ini");
150	    if (vendors_config_file.empty()) {
151	        OP_LOGW("aclnnfallback", "config.ini is not exists");
152	        return std::vector<std::string>();
153	    }
154	
155	    if (!is_file_exist(vendors_config_file)) {
156	        OP_LOGW("aclnnfallback", "config.ini is not exists or the path length is more than %d", OMNI_INFER_PATH_MAX);
157	        return std::vector<std::string>();
158	    }
159	
160	    std::ifstream ifs(vendors_config_file);
161	    std::string line;
162	    while (std::getline(ifs, line)) {
163	        if (line.find("load_priority=") == 0) {
164	            break;
165	        }
166	    }
167	    std::string head = "load_priority=";
168	    line.erase(0, head.length());
169	
170	    // split string with ","
171	    default_vendors_list = split_str(line, ",");
172	    if (default_vendors_list.empty()) {
173	        return std::vector<std::string>();
174	    }
175	    for (auto &it : default_vendors_list) {
176	        it = real_path(vendors_path + "/" + it + "/op_api/lib/");
177	    }
178	
179	    return default_vendors_list;
180	}
