192	inline void* GetOpApiFuncAddrInLib(void* handler, const char* libName, const char* apiName)
193	{
194	  auto funcAddr = dlsym(handler, apiName);
195	  if (funcAddr == nullptr) {
196	    OP_LOGW("aclnnfallback", "dlsym %s from %s failed, error:%s.", apiName, libName, dlerror());
197	  }
