201	inline void* GetOpApiLibHandler(const char* libName)
202	{
203	  auto handler = dlopen(libName, RTLD_LAZY);
204	  if (handler == nullptr) {
205	    OP_LOGW("aclnnfallback", "dlopen %s failed, error:%s.", libName, dlerror());
