210	inline void* GetAclnnArrdByApiName(const char *apiName)
211	{
212	    vector<std:: string> libs = {"libaclnn_ops_infer.so", "libaclnn_ops_train.so", "libaclnn_math.so",
213	                                 "libaclnn_rand.so", "libaclnn_sparse.so", "libaclnn_fft.so"};
214	    for (const auto &libName : libs) {
215	        static auto libHandler = GetOpApiLibHandler(libName.c_str());
216	        if (libHandler != nullptr) {
217	            auto funcAddr = GetOpApiFuncAddrInLib(libHandler, libName.c_str(), apiName);
218	            if (funcAddr != nullptr) {
219	                return funcAddr;
220	            }
221	        }
222	    }
223	    OP_LOGE("aclnnfallback", "api %s can't find in any aclnn lib.", apiName);
224	    return nullptr;
225	}
