227	inline void* GetOpApiFuncAddr(const char* apiName)
228	{
229	  const std::vector<std::string> custom_lib_path = get_custom_lib_path();
230	  const std::vector<std::string> default_custom_lib_path = get_default_custom_lib_path();
231	  if (!custom_lib_path.empty()) {
232	      for (auto &it : custom_lib_path) {
233	          auto cust_opapi_lib = real_path(it + "/" + GetCustOpApiLibName());
234	          if (cust_opapi_lib.empty()) {
235	              continue;
236	          }
237	          auto custOpApiHandler = GetOpApiLibHandler(cust_opapi_lib.c_str());
238	          if (custOpApiHandler != nullptr) {
239	              auto funcAddr =
240	                  GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
241	              if (funcAddr != nullptr) {
242	                  OP_LOGD("aclnnfallback", "%s is found in %s.", apiName, cust_opapi_lib.c_str());
243	                  return funcAddr;
244	              }
245	          }
246	      }
247	      OP_LOGD("aclnnfallback", "%s is not in custom lib.", apiName);
248	  }
249	  if (!default_custom_lib_path.empty()) {
250	      for (auto &it : default_custom_lib_path) {
251	          auto default_cust_opapi_lib = real_path(it + "/" + GetCustOpApiLibName());
252	          if (default_cust_opapi_lib.empty()) {
253	              continue;
254	          }
255	          auto custOpApiHandler = GetOpApiLibHandler(default_cust_opapi_lib.c_str());
256	          if (custOpApiHandler != nullptr) {
257	              auto funcAddr =
258	                  GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
259	              if (funcAddr != nullptr) {
260	                  OP_LOGD("aclnnfallback", "%s is found in %s.", apiName, default_cust_opapi_lib.c_str());
261	                  return funcAddr;
262	              }
263	          }
264	      }
265	      OP_LOGD("aclnnfallback", "%s is not in default custom lib.", apiName);
266	  }
267	
268	  OP_LOGD("aclnnfallback", "opapi lib is not exist,will use aclnn lib.");
269	  return GetAclnnArrdByApiName(apiName);
270	}
