287	inline aclDataType GetConvertType(const gert::Tensor* ge_tensor)
288	{
289	  // convert data type
290	  auto dataType_ge = ge_tensor->GetDataType();
291	  auto dataType = aclDataType::ACL_FLOAT16;
292	  if (dataType_ge == DT_FLOAT) {
293	    dataType = aclDataType::ACL_FLOAT;
294	  } else if (dataType_ge == DT_BF16) {
295	    dataType = aclDataType::ACL_BF16;
296	  } else if (dataType_ge == DT_BOOL) {
297	    dataType = aclDataType::ACL_BOOL;
298	  } else if (dataType_ge == DT_INT64) {
299	    dataType = aclDataType::ACL_INT64;
300	  } else if (dataType_ge == DT_INT32) {
301	    dataType = aclDataType::ACL_INT32;
302	  } else if (dataType_ge == DT_UINT64) {
303	    dataType = aclDataType::ACL_UINT64;
304	  } else if (dataType_ge == DT_UINT32) {
305	    dataType = aclDataType::ACL_UINT32;
306	  } else if (dataType_ge == DT_INT8) {
307	    dataType = aclDataType::ACL_INT8;
308	  } else if (dataType_ge == DT_UINT8) {
309	    dataType = aclDataType::ACL_UINT8;
310	  } else if (dataType_ge == DT_INT4) {
311	    dataType = aclDataType::ACL_INT4;
312	  } else {
313	    dataType = aclDataType::ACL_FLOAT16;
314	  }
315	
316	  return dataType;
317	}
318	
319	inline aclTensor* ConvertType(const gert::Tensor* ge_tensor)
320	{
321	  if (ge_tensor == nullptr) {
322	    return nullptr;
323	  }
324	
325	  static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
326	  OP_CHECK_IF(aclCreateTensor == nullptr, OP_LOGE("aclnnfallback", "aclCreateTensor nullptr"), return nullptr);
327	
328	  void* deviceAddr = nullptr;
329	  deviceAddr = const_cast<void*>(ge_tensor->GetAddr());
330	
331	  auto dataType = GetConvertType(ge_tensor);
332	
333	  OP_LOGD("aclnnfallback", "aclCreateTensor: tensor type is %d", dataType);
334	
335	  // convert shape
336	  auto gert_shape = ge_tensor->GetStorageShape();
337	  std::vector<int64_t> shape;
338	  for (size_t i = 0; i < gert_shape.GetDimNum(); ++i) {
339	    shape.push_back(gert_shape.GetDim(i));
340	  }
341	
342	  // 计算连续tensor的strides
343	  std::vector<int64_t> strides(shape.size(), 1);
344	  for (int64_t i = static_cast<int64_t>(shape.size()) - 2; i >= 0; i--) {
345	    strides[i] = shape[i + 1] * strides[i + 1];
346	  }
347	
348	  aclTensor* out = aclCreateTensor(shape.data(), shape.size(), dataType, strides.data(),
349	                                   0, aclFormat::ACL_FORMAT_ND,
350	                                   shape.data(), shape.size(), deviceAddr);
351	
352	  OP_CHECK_IF(out == nullptr,
353	    OP_LOGE("aclnnfallback", "out nullptr"), return nullptr);
354	
355	  return out;
356	}
