362	
363	  static const auto aclCreateTensorList = GET_OP_API_FUNC(aclCreateTensorList);
364	  OP_CHECK_IF(aclCreateTensorList == nullptr,
365	    OP_LOGE("aclnnfallback", "ge_tenserList size 0"), return nullptr);
366	
367	  std::vector<aclTensor*> tmp;
368	  for (size_t i = 0; i < ge_tenserList.size(); i++) {
369	    auto t_acl = ConvertType(ge_tenserList[i]);
370	    tmp.push_back(t_acl);
371	  }
372	
373	  aclTensorList* tensorList = aclCreateTensorList(tmp.data(), tmp.size());
374	  return tensorList;
375	}
