395	inline aclTensor* ConvertMmType(const gert::Tensor* ge_tensor, bool transpose, bool enable_NZ=false)
396	{
397	  if (ge_tensor == nullptr) {
398	    return nullptr;
399	  }
400	  auto gert_shape = ge_tensor->GetStorageShape();
401	  if (gert_shape.GetDimNum() <= 1) {
402	    return ConvertType(ge_tensor);
403	  }
404	
405	  static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
406	  OP_CHECK_IF(aclCreateTensor == nullptr, OP_LOGE("aclnnfallback", "aclCreateTensor nullptr"), return nullptr);
407	
408	  void* deviceAddr = const_cast<void*>(ge_tensor->GetAddr());
409	  // convert data type
410	  auto dataType_ge = ge_tensor->GetDataType();
411	  auto dataType = ToAclDataType(dataType_ge);
412	  // convert shape
413	  std::vector<int64_t> shape;
414	  for (size_t i = 0; i < gert_shape.GetDimNum(); ++i) {
415	    shape.push_back(gert_shape.GetDim(i));
416	  }
417	  // 计算连续tensor的strides
418	  std::vector<int64_t> strides(shape.size(), 1);
419	  for (int64_t i = static_cast<int64_t>(shape.size()) - 2; i >= 0; i--) {
420	    strides[i] = shape[i + 1] * strides[i + 1];
421	  }
422	
423	  auto viewShape = shape;
424	  // 对于transpose后的tensor对后两维度进行strides, viewShape转换
425	  if (transpose) {
426	    // dimM 为倒数第二维， dimN 为倒数第一维度
427	    auto dimM = shape.size() - 2;
428	    auto dimN = shape.size() - 1;
429	    auto swap =  strides[dimN];
430	    strides[dimN] = strides[dimM];
431	    strides[dimM] = swap;
432	    // 修改viewShape
433	    viewShape[dimN] = shape[dimM];
434	    viewShape[dimM] = shape[dimN];
435	  }
436	  auto acl_format = aclFormat::ACL_FORMAT_ND;
437	  if (enable_NZ && GetPrimaryFormat(ge_tensor->GetStorageFormat()) == ge::Format::FORMAT_FRACTAL_NZ) {
438	    acl_format = aclFormat::ACL_FORMAT_FRACTAL_NZ;
439	  }
440	  aclTensor* out = aclCreateTensor(viewShape.data(), shape.size(), dataType, strides.data(),
441	                                   0, acl_format, shape.data(), shape.size(), deviceAddr);
442	  OP_CHECK_IF(out == nullptr, OP_LOGE("aclnnfallback", "out nullptr"), return nullptr);
443	
444	  return out;
445	}
