526	template <typename Tuple, size_t... I>
527	auto ConvertToOpApiFunc(const Tuple& params, void* opApiAddr, std_utils::IndexSequence<I...>)
528	    -> int (*)(typename std::decay<decltype(std::get<I>(params))>::type...) 
529	{
530	    using OpApiFunc = int (*)(typename std::decay<decltype(std::get<I>(params))>::type...);
531	    auto func = reinterpret_cast<OpApiFunc>(opApiAddr);
532	    return func;
