536	auto ConvertToOpApiFunc(const Tuple &params, void *opApiAddr) ->
537	    typename std::enable_if<std::tuple_size<Tuple>::value != 0,
538	                            decltype(ConvertToOpApiFunc(
539	                                params, opApiAddr,
540	                                std_utils::make_index_sequence<
541	                                    std::tuple_size<Tuple>::value>{}))>::type 
542	{
543	  static constexpr auto size = std::tuple_size<Tuple>::value;
544	  return ConvertToOpApiFunc(params, opApiAddr,
545	                            std_utils::make_index_sequence<size>{});
546	}
