548	template <typename Tuple>
549	class ConvertedParams {
550	public:
551	  ConvertedParams(Tuple&& convertedParams) : convertedParams_(std::move(convertedParams)){};
552	  ConvertedParams(ConvertedParams&& other) : convertedParams_(std::move(other.convertedParams_))
553	  {
554	    other.validParams_ = false;
555	  };
556	  ConvertedParams& operator=(ConvertedParams&& other)
557	  {
558	    if (this == &other) {
559	      return *this;
560	    }
561	
562	    convertedParams_ = std::move(other.convertedParams_);
563	    validParams_ = true;
564	    other.validParams_ = false;
565	    return *this;
566	  }
