568	  ConvertedParams() = delete;
569	  ConvertedParams(const ConvertedParams& other) = delete;
570	  ConvertedParams& operator=(const ConvertedParams& other) = delete;
571	
572	  ~ConvertedParams()
573	  {
574	    if (validParams_) {
575	      ReleaseConvertTypes(convertedParams_);
576	    }
577	  }
578	
579	  const Tuple& GetConvertedParams() const
580	  {
581	    return convertedParams_;
582	  }
583	
584	private:
585	  Tuple convertedParams_;
586	  bool validParams_{true};
587	};
