599	#define EXEC_OPAPI_CMD(aclnn_api, ...)                                         \
600	  ({                                                                           \
601	    static auto ret = GRAPH_SUCCESS;                                           \
602	    do {                                                                       \
603	      static const auto ResetCacheThreadLocalAddr =                            \
604	          GetOpApiFuncAddr("ResetCacheThreadLocal");                           \
605	      static const auto getWorkspaceSizeFuncAddr =                             \
606	          GetOpApiFuncAddr(#aclnn_api "GetWorkspaceSize");                     \
607	      static const auto opApiFuncAddr = GetOpApiFuncAddr(#aclnn_api);          \
608	      if (getWorkspaceSizeFuncAddr == nullptr || opApiFuncAddr == nullptr ||   \
609	          ResetCacheThreadLocalAddr == nullptr) {                              \
610	        OP_LOGE(                                                               \
611	            "aclnnfallback",                                                   \
612	            "%s or %s not in  %s or %s  or ResetCacheThreadLocal not found.",  \
613	            #aclnn_api "GetWorkspaceSize", #aclnn_api, GetOpApiLibName(),      \
614	            GetOpApiLibName());                                                \
615	        ret = GRAPH_FAILED;                                                    \
616	        break;                                                                 \
617	      }                                                                        \
618	      auto ResetCacheThreadLocalFunc =                                         \
619	          reinterpret_cast<ResetCacheThreadLocal>(ResetCacheThreadLocalAddr);  \
620	      ResetCacheThreadLocalFunc();                                             \
621	      uint64_t workspace_size = 0;                                             \
622	      uint64_t *workspace_size_addr = &workspace_size;                         \
623	      aclOpExecutor *executor = nullptr;                                       \
624	      aclOpExecutor **executor_addr = &executor;                               \
625	      auto converted_params =                                                  \
626	          ConvertTypes(__VA_ARGS__, workspace_size_addr, executor_addr);       \
627	      static auto getWorkspaceSizeFunc =                                       \
628	          ConvertToOpApiFunc(converted_params, getWorkspaceSizeFuncAddr);      \
629	      auto workspace_status = call(getWorkspaceSizeFunc, converted_params);    \
630	      if (workspace_status != 0) {                                             \
631	        OP_LOGE("aclnnfallback", "call %s failed:", #aclnn_api);               \
632	        ret = GRAPH_FAILED;                                                    \
633	        break;                                                                 \
634	      }                                                                        \
635	      void *workspace_addr = nullptr;                                          \
636	      if (workspace_size > 0) {                                                \
637	        workspace_addr = host_api_ctx->MallocWorkspace(workspace_size);        \
638	        if (workspace_addr == nullptr) {                                       \
639	          OP_LOGE("aclnnfallback", "call %s allocate workspace failed",        \
640	                  #aclnn_api);                                                 \
641	          ret = GRAPH_FAILED;                                                  \
642	          break;                                                               \
643	        }                                                                      \
644	      }                                                                        \
645	      auto acl_stream = host_api_ctx->GetStream();                             \
646	      auto acl_call = [converted_params, workspace_addr, workspace_size,       \
647	                       host_api_ctx, acl_stream, executor]() -> int {          \
648	        using OpApiFunc =                                                      \
649	            int (*)(void *, uint64_t, aclOpExecutor *, const aclrtStream);     \
650	        OpApiFunc opApiFunc = reinterpret_cast<OpApiFunc>(opApiFuncAddr);      \
651	        auto api_ret_inner =                                                   \
652	            opApiFunc(workspace_addr, workspace_size, executor, acl_stream);   \
653	        ReleaseConvertTypes(converted_params);                                 \
654	        host_api_ctx->FreeWorkspace();                                         \
655	        if (api_ret_inner != 0) {                                              \
656	          OP_LOGE("aclnnfallback",                                             \
657	                  "call %s allocate workspace failed api_ret_inner: %d",       \
658	                  #aclnn_api, api_ret_inner);                                  \
659	          return GRAPH_FAILED;                                                 \
660	        }                                                                      \
661	        return api_ret_inner;                                                  \
662	      };                                                                       \
663	                                                                               \
664	      ret = acl_call();                                                        \
665	    } while (false);                                                           \
666	    (ret);                                                                     \
667	  })
668	
669	}  // namespace fallback
670	
671	#endif  //  ACLNNFALLBACK_OPAPI_H_

