#define GET_OP_API_FUNC(apiName) reinterpret_cast<_##apiName>(GetOpApiFuncAddr(#apiName))
#define OMNI_INFER_PATH_MAX 4096

inline std::vector<std::string> split_str(std::string s, const std::string &del)
{
    size_t end = s.find(del);
    std::vector<std::string> path_list;
    while (end != std::string::npos) {
        path_list.push_back(s.substr(0, end));
        s.erase(s.begin(), s.begin() + end + 1);
        end = s.find(del);
    }
    path_list.push_back(s);
    return path_list;
}

inline bool is_file_exist(const std::string &path)
{
    if (path.empty() || path.size() > OMNI_INFER_PATH_MAX) {
        return false;
    }
    return (access(path.c_str(), F_OK) == 0) ? true : false;
}

inline  std::string real_path(const std::string &path)
{
    if (path.empty() || path.size() > OMNI_INFER_PATH_MAX) {
        return "";
    }
    char realPath[OMNI_INFER_PATH_MAX] = {0};
    if (realpath(path.c_str(), realPath) == nullptr) {
        return "";
    }
    return std::string(realPath);
}

inline std::vector<std::string> get_custom_lib_path()
{
    std::string ascendCustomOpppath = std::getenv("ASCEND_CUSTOM_OPP_PATH");
    std::vector<std::string> custom_lib_path_list;

    if (ascendCustomOpppath.empty()) {
        OP_LOGW("aclnnfallback", "ASCEND_CUSTOM_OPP_PATH is not exists");
        return std::vector<std::string>();
    }

    std::string ascend_custom_opppath_str(ascendCustomOpppath);
    // split string with ":"
    custom_lib_path_list = split_str(ascend_custom_opppath_str, ":");
    if (custom_lib_path_list.empty()) {
        return std::vector<std::string>();
    }
    for (auto &it : custom_lib_path_list) {
        it = it + "/op_api/lib/";
    }

    return custom_lib_path_list;
}

inline std::vector<std::string> get_default_custom_lib_path()
{
    std::string ascendOppPath = std::getenv("ASCEND_OPP_PATH");
    std::vector<std::string> default_vendors_list;

    if (ascendOppPath.empty()) {
        OP_LOGW("aclnnfallback", "ASCEND_OPP_PATH is not exists");
        return std::vector<std::string>();
    }

    std::string vendors_path(ascendOppPath);
    vendors_path = vendors_path + "/vendors";
    std::string vendors_config_file = real_path(vendors_path + "/config.ini");
    if (vendors_config_file.empty()) {
        OP_LOGW("aclnnfallback", "config.ini is not exists");
        return std::vector<std::string>();
    }

    if (!is_file_exist(vendors_config_file)) {
        OP_LOGW("aclnnfallback", "config.ini is not exists or the path length is more than %d", OMNI_INFER_PATH_MAX);
        return std::vector<std::string>();
    }

    std::ifstream ifs(vendors_config_file);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.find("load_priority=") == 0) {
            break;
        }
    }
    std::string head = "load_priority=";
    line.erase(0, head.length());

    // split string with ","
    default_vendors_list = split_str(line, ",");
    if (default_vendors_list.empty()) {
        return std::vector<std::string>();
    }
    for (auto &it : default_vendors_list) {
        it = real_path(vendors_path + "/" + it + "/op_api/lib/");
    }

    return default_vendors_list;
}

inline const char* GetOpApiLibName(void)
{
  return "libopapi.so";
}

inline const char* GetCustOpApiLibName(void)
{
  return "libcust_opapi.so";
}

inline void* GetOpApiFuncAddrInLib(void* handler, const char* libName, const char* apiName)
{
  auto funcAddr = dlsym(handler, apiName);
  if (funcAddr == nullptr) {
    OP_LOGW("aclnnfallback", "dlsym %s from %s failed, error:%s.", apiName, libName, dlerror());
  }
  return funcAddr;
}

inline void* GetOpApiLibHandler(const char* libName)
{
  auto handler = dlopen(libName, RTLD_LAZY);
  if (handler == nullptr) {
    OP_LOGW("aclnnfallback", "dlopen %s failed, error:%s.", libName, dlerror());
  }
  return handler;
}

inline void* GetAclnnArrdByApiName(const char *apiName)
{
    vector<std:: string> libs = {"libaclnn_ops_infer.so", "libaclnn_ops_train.so", "libaclnn_math.so",
                                 "libaclnn_rand.so", "libaclnn_sparse.so", "libaclnn_fft.so"};
    for (const auto &libName : libs) {
        static auto libHandler = GetOpApiLibHandler(libName.c_str());
        if (libHandler != nullptr) {
            auto funcAddr = GetOpApiFuncAddrInLib(libHandler, libName.c_str(), apiName);
            if (funcAddr != nullptr) {
                return funcAddr;
            }
        }
    }
    OP_LOGE("aclnnfallback", "api %s can't find in any aclnn lib.", apiName);
    return nullptr;
}

inline void* GetOpApiFuncAddr(const char* apiName)
{
  const std::vector<std::string> custom_lib_path = get_custom_lib_path();
  const std::vector<std::string> default_custom_lib_path = get_default_custom_lib_path();
  if (!custom_lib_path.empty()) {
      for (auto &it : custom_lib_path) {
          auto cust_opapi_lib = real_path(it + "/" + GetCustOpApiLibName());
          if (cust_opapi_lib.empty()) {
              continue;
          }
          auto custOpApiHandler = GetOpApiLibHandler(cust_opapi_lib.c_str());
          if (custOpApiHandler != nullptr) {
              auto funcAddr =
                  GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
              if (funcAddr != nullptr) {
                  OP_LOGD("aclnnfallback", "%s is found in %s.", apiName, cust_opapi_lib.c_str());
                  return funcAddr;
              }
          }
      }
      OP_LOGD("aclnnfallback", "%s is not in custom lib.", apiName);
  }
  if (!default_custom_lib_path.empty()) {
      for (auto &it : default_custom_lib_path) {
          auto default_cust_opapi_lib = real_path(it + "/" + GetCustOpApiLibName());
          if (default_cust_opapi_lib.empty()) {
              continue;
          }
          auto custOpApiHandler = GetOpApiLibHandler(default_cust_opapi_lib.c_str());
          if (custOpApiHandler != nullptr) {
              auto funcAddr =
                  GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
              if (funcAddr != nullptr) {
                  OP_LOGD("aclnnfallback", "%s is found in %s.", apiName, default_cust_opapi_lib.c_str());
                  return funcAddr;
              }
          }
      }
      OP_LOGD("aclnnfallback", "%s is not in default custom lib.", apiName);
  }

  OP_LOGD("aclnnfallback", "opapi lib is not exist,will use aclnn lib.");
  return GetAclnnArrdByApiName(apiName);
}

inline aclTensor* ConvertType(aclTensor* geTensor)
{
  return geTensor;
}

inline aclIntArray* ConvertType(const std::vector<int64_t> &arr)
{
  if (arr.empty()) {
    return nullptr;
  }
  static const auto aclCreateIntArray = GET_OP_API_FUNC(aclCreateIntArray);
  auto array = aclCreateIntArray(arr.data(), arr.size());
  return array;
}

inline aclDataType GetConvertType(const gert::Tensor* ge_tensor)
{
  // convert data type
  auto dataType_ge = ge_tensor->GetDataType();
  auto dataType = aclDataType::ACL_FLOAT16;
  if (dataType_ge == DT_FLOAT) {
    dataType = aclDataType::ACL_FLOAT;
  } else if (dataType_ge == DT_BF16) {
    dataType = aclDataType::ACL_BF16;
  } else if (dataType_ge == DT_BOOL) {
    dataType = aclDataType::ACL_BOOL;
  } else if (dataType_ge == DT_INT64) {
    dataType = aclDataType::ACL_INT64;
  } else if (dataType_ge == DT_INT32) {
    dataType = aclDataType::ACL_INT32;
  } else if (dataType_ge == DT_UINT64) {
    dataType = aclDataType::ACL_UINT64;
  } else if (dataType_ge == DT_UINT32) {
    dataType = aclDataType::ACL_UINT32;
  } else if (dataType_ge == DT_INT8) {
    dataType = aclDataType::ACL_INT8;
  } else if (dataType_ge == DT_UINT8) {
    dataType = aclDataType::ACL_UINT8;
  } else if (dataType_ge == DT_INT4) {
    dataType = aclDataType::ACL_INT4;
  } else {
    dataType = aclDataType::ACL_FLOAT16;
  }

  return dataType;
}

inline aclTensor* ConvertType(const gert::Tensor* ge_tensor)
{
  if (ge_tensor == nullptr) {
    return nullptr;
  }

  static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
  OP_CHECK_IF(aclCreateTensor == nullptr, OP_LOGE("aclnnfallback", "aclCreateTensor nullptr"), return nullptr);

  void* deviceAddr = nullptr;
  deviceAddr = const_cast<void*>(ge_tensor->GetAddr());

  auto dataType = GetConvertType(ge_tensor);

  OP_LOGD("aclnnfallback", "aclCreateTensor: tensor type is %d", dataType);

  // convert shape
  auto gert_shape = ge_tensor->GetStorageShape();
  std::vector<int64_t> shape;
  for (size_t i = 0; i < gert_shape.GetDimNum(); ++i) {
    shape.push_back(gert_shape.GetDim(i));
  }

  // 计算连续tensor的strides
  std::vector<int64_t> strides(shape.size(), 1);
  for (int64_t i = static_cast<int64_t>(shape.size()) - 2; i >= 0; i--) {
    strides[i] = shape[i + 1] * strides[i + 1];
  }

  aclTensor* out = aclCreateTensor(shape.data(), shape.size(), dataType, strides.data(),
                                   0, aclFormat::ACL_FORMAT_ND,
                                   shape.data(), shape.size(), deviceAddr);

  OP_CHECK_IF(out == nullptr,
    OP_LOGE("aclnnfallback", "out nullptr"), return nullptr);

  return out;
}

inline aclTensorList* ConvertType(std::vector<const gert::Tensor*>& ge_tenserList)
{
  OP_CHECK_IF(ge_tenserList.size() == 0,
    OP_LOGE("aclnnfallback", "ge_tenserList size 0"), return nullptr);

  static const auto aclCreateTensorList = GET_OP_API_FUNC(aclCreateTensorList);
  OP_CHECK_IF(aclCreateTensorList == nullptr,
    OP_LOGE("aclnnfallback", "ge_tenserList size 0"), return nullptr);

  std::vector<aclTensor*> tmp;
  for (size_t i = 0; i < ge_tenserList.size(); i++) {
    auto t_acl = ConvertType(ge_tenserList[i]);
    tmp.push_back(t_acl);
  }

  aclTensorList* tensorList = aclCreateTensorList(tmp.data(), tmp.size());
  return tensorList;
}

template <typename T>
inline aclScalar* ConvertScalarType(T value)
{
  static const auto aclCreateScalar = GET_OP_API_FUNC(aclCreateScalar);
  OP_CHECK_IF(aclCreateScalar == nullptr,
    OP_LOGE("aclnnfallback", "aclCreateScalar nullptr"), return nullptr);
  if (typeid(value) == typeid(float)) {
    return aclCreateScalar(&value, aclDataType::ACL_FLOAT);
  }
  return nullptr;
}

template <typename T>
T ConvertType(T value)
{
  return value;
}

inline aclTensor* ConvertMmType(const gert::Tensor* ge_tensor, bool transpose, bool enable_NZ=false)
{
  if (ge_tensor == nullptr) {
    return nullptr;
  }
  auto gert_shape = ge_tensor->GetStorageShape();
  if (gert_shape.GetDimNum() <= 1) {
    return ConvertType(ge_tensor);
  }

  static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
  OP_CHECK_IF(aclCreateTensor == nullptr, OP_LOGE("aclnnfallback", "aclCreateTensor nullptr"), return nullptr);

  void* deviceAddr = const_cast<void*>(ge_tensor->GetAddr());
  // convert data type
  auto dataType_ge = ge_tensor->GetDataType();
  auto dataType = ToAclDataType(dataType_ge);
  // convert shape
  std::vector<int64_t> shape;
  for (size_t i = 0; i < gert_shape.GetDimNum(); ++i) {
    shape.push_back(gert_shape.GetDim(i));
  }
  // 计算连续tensor的strides
  std::vector<int64_t> strides(shape.size(), 1);
  for (int64_t i = static_cast<int64_t>(shape.size()) - 2; i >= 0; i--) {
    strides[i] = shape[i + 1] * strides[i + 1];
  }

  auto viewShape = shape;
  // 对于transpose后的tensor对后两维度进行strides, viewShape转换
  if (transpose) {
    // dimM 为倒数第二维， dimN 为倒数第一维度
    auto dimM = shape.size() - 2;
    auto dimN = shape.size() - 1;
    auto swap =  strides[dimN];
    strides[dimN] = strides[dimM];
    strides[dimM] = swap;
    // 修改viewShape
    viewShape[dimN] = shape[dimM];
    viewShape[dimM] = shape[dimN];
  }
  auto acl_format = aclFormat::ACL_FORMAT_ND;
  if (enable_NZ && GetPrimaryFormat(ge_tensor->GetStorageFormat()) == ge::Format::FORMAT_FRACTAL_NZ) {
    acl_format = aclFormat::ACL_FORMAT_FRACTAL_NZ;
  }
  aclTensor* out = aclCreateTensor(viewShape.data(), shape.size(), dataType, strides.data(),
                                   0, acl_format, shape.data(), shape.size(), deviceAddr);
  OP_CHECK_IF(out == nullptr, OP_LOGE("aclnnfallback", "out nullptr"), return nullptr);

  return out;
}

