constexpr size_t ATTR_COMPRESS_BLOCK_SIZE_INDEX = 5;

// OUTPUT
constexpr size_t TOP_K_INDEX = 0;

struct AiInfraEsaSelectTopkFallBackParam {
    const gert::Tensor *query = nullptr;
    const gert::Tensor *key = nullptr;

    const gert::Tensor *actualSeqLengthsQGe = nullptr;
    const gert::Tensor *actualSeqLengthsKGe = nullptr;
    const gert::Tensor *actualSeqLengthsCmpKGe = nullptr;

    int64_t blockSize;
    int64_t initBlkNum;
    int64_t localBlkNum;
    int64_t topK;
    const char *inputLayout = nullptr;
    int64_t compressBlockSize;

    const gert::Tensor *topk_indices = nullptr;
};

graphStatus GetAiInfraEsaSelectTopKInputTensor(const OpExecuteContext *ctx, AiInfraEsaSelectTopkFallBackParam &param)
{
    param.query = ctx->GetRequiredInputTensor(QUERY_INDEX);
    OPS_CHECK(param.query == nullptr, OPS_LOG_E("aclnnfallback", "query is null"), return GRAPH_FAILED);

    param.key = ctx->GetRequiredInputTensor(KEY_INDEX);
    OPS_CHECK(param.key == nullptr, OPS_LOG_E("aclnnfallback", "key is null"), return GRAPH_FAILED);
    return GRAPH_SUCCESS;
}

graphStatus GetAiInfraEsaSelectTopKOutputTensor(const OpExecuteContext *ctx, AiInfraEsaSelectTopkFallBackParam &param)
{
    param.topk_indices = ctx->GetOutputTensor(TOP_K_INDEX);
    OPS_CHECK(param.topk_indices == nullptr, OPS_LOG_E("aclnnfallback", "topk_indices is null"), return GRAPH_FAILED);
    return GRAPH_SUCCESS;
}

graphStatus GetAiInfraEsaSelectTopKAttr(const OpExecuteContext *ctx, AiInfraEsaSelectTopkFallBackParam &param)
{
    auto attrs = ctx->GetAttrs();
    const int64_t *blockSize = attrs->GetAttrPointer<int64_t>(ATTR_BLOCK_SIZE_INDEX);
    const int64_t *initBlkNum = attrs->GetAttrPointer<int64_t>(ATTR_INIT_BLK_NUM_INDEX);
    const int64_t *localBlkNum = attrs->GetAttrPointer<int64_t>(ATTR_LOCAL_BLK_NUM_INDEX);
    const int64_t *topK = attrs->GetAttrPointer<int64_t>(ATTR_TOPK_INDEX);
    const char *inputLayout = attrs->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX);
    const int64_t *compressBlockSize = attrs->GetAttrPointer<int64_t>(ATTR_COMPRESS_BLOCK_SIZE_INDEX);

    param.blockSize = *blockSize;
    param.initBlkNum = *initBlkNum;
    param.localBlkNum = *localBlkNum;
    param.topK = *topK;
    param.inputLayout = inputLayout;
    param.compressBlockSize = *compressBlockSize;

    OPS_LOG_D("aclnnFallback",
              "AiInfraEsaSelectTopK fallback begin, blockSize = %f, initBlkNum = %f",
              param.blockSize,
              param.initBlkNum);
    return GRAPH_SUCCESS;
}

graphStatus GetAiInfraEsaSelectTopKOption(const OpExecuteContext *ctx, AiInfraEsaSelectTopkFallBackParam &param)
{
    param.actualSeqLengthsQGe = ctx->GetRequiredInputTensor(ACTUAL_Q_LEN_INDEX);
    param.actualSeqLengthsKGe = ctx->GetRequiredInputTensor(ACTUAL_K_LEN_INDEX);
    param.actualSeqLengthsCmpKGe = ctx->GetRequiredInputTensor(ACTUAL_CMPK_LEN_INDEX);

    std::string inputLayoutStr = std::string(param.inputLayout);
    if (inputLayoutStr == "TND") {
        OPS_CHECK(param.actualSeqLengthsQGe == nullptr,
                  OPS_LOG_E("aclnnfallback", "actualSeqLengthsQGe is null"),
                  return GRAPH_FAILED);
        OPS_CHECK(param.actualSeqLengthsKGe == nullptr,
                  OPS_LOG_E("aclnnfallback", "actualSeqLengthsKGe is null"),
                  return GRAPH_FAILED);
        OPS_CHECK(param.actualSeqLengthsCmpKGe == nullptr,
                  OPS_LOG_E("aclnnfallback", "actualSeqLengthsCmpKGe is null"),
                  return GRAPH_FAILED);
    }
    return GRAPH_SUCCESS;
}

struct EsaActualSeqInfo {
    std::vector<int64_t> actSeqQArray;
    std::vector<int64_t> actSeqKArray;
    std::vector<int64_t> actSeqCmpKArray;
};

static void EsaFillActualSeqInfo(const AiInfraEsaSelectTopkFallBackParam &param, EsaActualSeqInfo &easActualSeqInfo)
{
    if (param.actualSeqLengthsQGe != nullptr) {
        const int64_t *actSeqData = param.actualSeqLengthsQGe->GetData<int64_t>();
        const size_t len = static_cast<size_t>(param.actualSeqLengthsQGe->GetShapeSize());
        for (size_t i = 0; i < len; i++) {
            easActualSeqInfo.actSeqQArray.push_back(actSeqData[i]);
        }
    }

    if (param.actualSeqLengthsKGe != nullptr) {
        const int64_t *actSeqData = param.actualSeqLengthsKGe->GetData<int64_t>();
        const size_t len = static_cast<size_t>(param.actualSeqLengthsKGe->GetShapeSize());
        for (size_t i = 0; i < len; i++) {
            easActualSeqInfo.actSeqKArray.push_back(actSeqData[i]);
        }
    }

    if (param.actualSeqLengthsCmpKGe != nullptr) {
        const int64_t *actSeqData = param.actualSeqLengthsCmpKGe->GetData<int64_t>();
        const size_t len = static_cast<size_t>(param.actualSeqLengthsCmpKGe->GetShapeSize());
        for (size_t i = 0; i < len; i++) {
            easActualSeqInfo.actSeqCmpKArray.push_back(actSeqData[i]);
        }
    }
}

graphStatus AiInfraEsaSelectTopkHostExecuteFunc(OpExecuteContext *host_api_ctx)
{
    OPS_CHECK(host_api_ctx == nullptr, OPS_LOG_E("aclnnfallback", "host_api_ctx is null"), return GRAPH_FAILED);

    AiInfraEsaSelectTopkFallBackParam param{};
    auto apiRet = GetAiInfraEsaSelectTopKInputTensor(host_api_ctx, param);
    OPS_CHECK(
        apiRet != GRAPH_SUCCESS, OPS_LOG_E("aclnnfallback", "Context get input tesnor failed"), return GRAPH_FAILED);

    apiRet = GetAiInfraEsaSelectTopKOutputTensor(host_api_ctx, param);
    OPS_CHECK(
        apiRet != GRAPH_SUCCESS, OPS_LOG_E("aclnnfallback", "Context get output tesnor failed"), return GRAPH_FAILED);

    apiRet = GetAiInfraEsaSelectTopKAttr(host_api_ctx, param);
    OPS_CHECK(apiRet != GRAPH_SUCCESS, OPS_LOG_E("aclnnfallback", "Context get attr failed"), return GRAPH_FAILED);

    apiRet = GetAiInfraEsaSelectTopKOption(host_api_ctx, param);
    OPS_CHECK(apiRet != GRAPH_SUCCESS, OPS_LOG_E("aclnnfallback", "Context get option failed"), return GRAPH_FAILED);

    EsaActualSeqInfo easActualSeqInfo{};
    EsaFillActualSeqInfo(param, easActualSeqInfo);
    apiRet = EXEC_OPAPI_CMD(aclnnAiInfraEsaSelectTopk,
                            param.query,
                            param.key,
                            easActualSeqInfo.actSeqQArray,
                            easActualSeqInfo.actSeqKArray,
                            easActualSeqInfo.actSeqCmpKArray,
                            param.blockSize,
                            param.initBlkNum,
                            param.localBlkNum,
                            param.topK,
                            param.inputLayout,
                            param.compressBlockSize,
                            param.topk_indices);
    OPS_CHECK(apiRet != GRAPH_SUCCESS, OPS_LOG_E("aclnnfallback", "ret failed:%u", apiRet), return GRAPH_FAILED);
    return GRAPH_SUCCESS;
}

IMPL_OP(AiInfraEsaSelectTopk)
    .OpExecuteFunc(AiInfraEsaSelectTopkHostExecuteFunc)
    .HostInputs({ACTUAL_Q_LEN_INDEX, ACTUAL_K_LEN_INDEX, ACTUAL_CMPK_LEN_INDEX});
} // namespace fallback

