graphStatus GetAiInfraEsaSelectTopkInputTensor(const OpExecuteContext *ctx, AiInfraEsaSelectTopkFallBackParam &param);
graphStatus GetAiInfraEsaSelectTopkOutputTensor(const OpExecuteContext *ctx, AiInfraEsaSelectTopkFallBackParam &param);
graphStatus GetAiInfraEsaSelectTopkAttr(const OpExecuteContext *ctx, AiInfraEsaSelectTopkFallBackParam &param);
