81	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetPlatformInfo()
82	{
83	    uint64_t aivNum = 40;
84	    uint64_t ubSize = 192 * 1024; // 192k: default ubSize
85	    auto platformInfoPtr = context_->GetPlatformInfo();
86	    if (platformInfoPtr == nullptr) {
87	        auto compilePtr = reinterpret_cast<const AiInfraScatterBlockUpdateCompileInfo *>(context_->GetCompileInfo());
88	        OP_CHECK_IF(compilePtr == nullptr, OP_LOGE(context_, "compile_info is null"),
89	                    return ge::GRAPH_FAILED);
90	        aivNum = compilePtr->aivNum;
91	        ubSize = compilePtr->ubSize;
92	    } else {
93	        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
94	        aivNum = ascendcPlatform.GetCoreNumAiv();
95	        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
96	    }
97	    aivNum_ = aivNum;
98	    ubSize_ = static_cast<int64_t>(ubSize);
99	
100	    return ge::GRAPH_SUCCESS;
101	}
