177	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetUpdateShape()
178	{
179	    // ========== 获取update信息: shape (T, D), 连续, 与input同dtype ==========
180	    auto updateDesc = context_->GetInputDesc(INPUT_UPDATE_INDEX);
181	    OP_CHECK_NULL_WITH_CONTEXT(context_, updateDesc);
182	    auto updateDtype = updateDesc->GetDataType();
183	
184	    OP_CHECK_IF(updateDtype != inputDtype_,
185	        OP_LOGE(context_->GetNodeName(), "update dtype should be same as input dtype"),
186	        return ge::GRAPH_FAILED);
187	
188	    auto updateShapePtr = context_->GetInputShape(INPUT_UPDATE_INDEX);
189	    OP_CHECK_NULL_WITH_CONTEXT(context_, updateShapePtr);
190	    auto updateShape = updateShapePtr->GetStorageShape();
191	
192	    OP_CHECK_IF(updateShape.GetDimNum() != static_cast<size_t>(UPDATE_DIM_NUM),
193	        OP_LOGE(context_->GetNodeName(),
194	                "update should be 2D (T, D), but got %zu dims", updateShape.GetDimNum()),
195	        return ge::GRAPH_FAILED);
196	
197	    int64_t updateT = updateShape.GetDim(0);
198	    updateDimSize_ = updateShape.GetDim(1);
199	
200	    // 校验indices和update的T维一致
201	    OP_CHECK_IF(updateT != T_,
202	        OP_LOGE(context_->GetNodeName(),
203	                "update dim0(%ld) should match indices dim0(%ld)", updateT, T_),
204	        return ge::GRAPH_FAILED);
205	
206	    // 校验update的D维与input的D维一致
207	    OP_CHECK_IF(updateDimSize_ != D_,
208	        OP_LOGE(context_->GetNodeName(),
209	                "update dim1(%ld) should match input dim2(%ld)", updateDimSize_, D_),
210	        return ge::GRAPH_FAILED);
211	    return ge::GRAPH_SUCCESS;
212	}
