214	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::ValidateShapeRange()
215	{
216	    // ========== shape取值范围校验 ==========
217	    OP_CHECK_IF(bn_ < BN_MIN || bn_ > BN_MAX,
218	        OP_LOGE(context_->GetNodeName(),
219	                "b_n(%ld) out of range [%ld, %ld]", bn_, BN_MIN, BN_MAX),
220	        return ge::GRAPH_FAILED);
221	    OP_CHECK_IF(bs_ < BS_MIN || bs_ > BS_MAX,
222	        OP_LOGE(context_->GetNodeName(),
223	                "b_s(%ld) out of range [%ld, %ld]", bs_, BS_MIN, BS_MAX),
224	        return ge::GRAPH_FAILED);
225	    OP_CHECK_IF(D_ < D_MIN || D_ > D_MAX,
226	        OP_LOGE(context_->GetNodeName(),
227	                "D(%ld) out of range [%ld, %ld]", D_, D_MIN, D_MAX),
228	        return ge::GRAPH_FAILED);
229	    OP_CHECK_IF(T_ < T_MIN || T_ > T_MAX,
230	        OP_LOGE(context_->GetNodeName(),
231	                "T(%ld) out of range [%ld, %ld]", T_, T_MIN, T_MAX),
232	        return ge::GRAPH_FAILED);
233	    return ge::GRAPH_SUCCESS;
234	}
