236	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::CalcDataTypeSize()
237	{
238	    // ========== 计算数据类型大小 ==========
239	    indicesTypeSize_ = ge::GetSizeByDataType(indicesDtype_);
240	    OP_CHECK_IF(indicesTypeSize_ <= 0,
241	        OP_LOGE(context_->GetNodeName(), "get indicesTypeSize failed"),
242	        return ge::GRAPH_FAILED);
243	
244	    updateTypeSize_ = ge::GetSizeByDataType(inputDtype_);
245	    OP_CHECK_IF(updateTypeSize_ <= 0,
246	        OP_LOGE(context_->GetNodeName(), "get updateTypeSize failed"),
247	        return ge::GRAPH_FAILED);
248	    return ge::GRAPH_SUCCESS;
249	}
