376	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::PostTiling()
377	{
378	    // ========== 设置所有TilingData字段 ==========
379	    tilingData_.set_totalIndicesCount(totalIndicesCount_);
380	    tilingData_.set_updateDimSize(updateDimSize_);
381	    tilingData_.set_totalCoreNum(totalCoreNum_);
382	    tilingData_.set_ubSize(ubSize_);
383	    tilingData_.set_eachCoreIndexCount(eachCoreIndexCount_);
384	    tilingData_.set_usedCoreNum(usedCoreNum_);
385	    tilingData_.set_tailCoreIndexCount(tailCoreIndexCount_);
386	    tilingData_.set_oneIndexSize(oneIndexSize_);
387	    tilingData_.set_oneUpdateAlignSize(oneUpdateAlignSize_);
388	    tilingData_.set_indicesPerLoad(indicesPerLoad_);
389	    tilingData_.set_maxIndicesPerLoad(maxIndicesPerLoad_);
390	    tilingData_.set_inputStride0(inputStride0_);
391	    tilingData_.set_inputStride1(inputStride1_);
392	    tilingData_.set_indicesTypeSize(indicesTypeSize_);
393	    tilingData_.set_updateTypeSize(updateTypeSize_);
394	
395	    PrintTilingData();
396	
397	    // 校验TilingData大小对齐到8字节
398	    OP_CHECK_IF(tilingData_.GetDataSize() % sizeof(uint64_t) != 0,
399	        OP_LOGE(context_->GetNodeName(), "tiling data size[%zu] is not aligned to 8", tilingData_.GetDataSize()),
400	        return ge::GRAPH_FAILED);
401	
402	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetRawTilingData());
403	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
404	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
405	
406	    // 设置block维度（实际使用的核数）
407	    context_->SetBlockDim(usedCoreNum_);
408	
409	    // 设置workspace（本算子为原地更新，不需要额外workspace）
410	    size_t *workspaces = context_->GetWorkspaceSizes(1);
411	    OP_CHECK_IF(workspaces == nullptr, OPS_REPORT_CUBE_INNER_ERR(context_->GetNodeName(), "workspaces is null"),
412	        return ge::GRAPH_FAILED);
413	    workspaces[0] = workspaceSize_;
414	
415	    return ge::GRAPH_SUCCESS;
416	}
